#!/usr/bin/env python3
"""Flask REST API exposing a single text-transformation endpoint."""

from __future__ import annotations

from typing import Any, Callable, Dict, Tuple, Union

from flask import Flask, Response, jsonify, request

app = Flask(__name__)

# Map of supported operation names to the callable that produces the result.
OPERATIONS: Dict[str, Callable[[str], Union[str, int]]] = {
    "uppercase": lambda text: text.upper(),
    "reverse": lambda text: text[::-1],
    "count_words": lambda text: len(text.split()),
}


def error(message: str, status: int = 400) -> Tuple[Response, int]:
    """Build a JSON error response with the given message and status code."""
    return jsonify({"error": message}), status


@app.route("/api/transform", methods=["POST"])
def transform() -> Tuple[Response, int]:
    """Transform a text string according to the requested operation.

    Expects a JSON body of the form::

        {"text": "Hello World", "operation": "uppercase"}

    Supported operations are ``uppercase``, ``reverse`` and ``count_words``.

    Returns:
        A ``(response, status_code)`` tuple. On success the status is 200 and the
        JSON payload contains ``result``, ``operation`` and ``original_length``.
        On any validation failure the status is 400 and the payload contains a
        single ``error`` key describing the problem.
    """
    payload: Any = request.get_json(silent=True)

    if payload is None:
        return error("Request body must be valid JSON")
    if not isinstance(payload, dict):
        return error("Request body must be a JSON object")

    if "text" not in payload:
        return error("Missing required field: 'text'")
    text: Any = payload["text"]
    if not isinstance(text, str):
        return error("Field 'text' must be a string")

    if "operation" not in payload:
        return error("Missing required field: 'operation'")
    operation: Any = payload["operation"]
    if not isinstance(operation, str) or operation not in OPERATIONS:
        supported = ", ".join(sorted(OPERATIONS))
        return error(f"Field 'operation' must be one of: {supported}")

    result: Union[str, int] = OPERATIONS[operation](text)

    return (
        jsonify(
            {
                "result": result,
                "operation": operation,
                "original_length": len(text),
            }
        ),
        200,
    )


if __name__ == "__main__":
    app.run(debug=True, port=5000)
```

Notes on the details:

- **`get_json(silent=True)`** returns `None` for malformed/non-JSON bodies instead of raising a 400 HTML error page, so every failure path returns your JSON shape. A literal `null` body also lands here, which is the desired outcome anyway.
- **`isinstance(payload, dict)` check** guards against valid-but-wrong JSON like `[1, 2]` or `"hi"`, where `payload["text"]` would raise a `TypeError`.
- **Booleans and `text`**: `isinstance(True, str)` is `False`, so `{"text": true}` is correctly rejected.
- **`jsonify`** sets `Content-Type: application/json` automatically on both success and error responses.
- **`count_words`** uses `str.split()` with no argument, which collapses runs of arbitrary whitespace and ignores leading/trailing whitespace — `"  a   b  "` counts as 2.

Run with `pip install flask && python app.py`, then:

```bash
curl -X POST http://localhost:5000/api/transform \
  -H 'Content-Type: application/json' \
  -d '{"text": "Hello World", "operation": "reverse"}'
```

