from typing import Any

from flask import Flask, Response, jsonify, request

app = Flask(__name__)

SUPPORTED_OPERATIONS = {"uppercase", "reverse", "count_words"}


@app.post("/api/transform")
def transform_text() -> tuple[Response, int]:
    """Validate a JSON request and perform the requested text transformation."""
    body: Any = request.get_json(silent=True)

    if body is None:
        return jsonify(error="Request body must contain valid JSON"), 400

    if not isinstance(body, dict):
        return jsonify(error="Request body must be a JSON object"), 400

    text = body.get("text")
    if not isinstance(text, str):
        return jsonify(error="The 'text' field is required and must be a string"), 400

    operation = body.get("operation")
    if not isinstance(operation, str) or operation not in SUPPORTED_OPERATIONS:
        return (
            jsonify(
                error=(
                    "The 'operation' field is required and must be one of: "
                    "uppercase, reverse, count_words"
                )
            ),
            400,
        )

    if operation == "uppercase":
        result: str | int = text.upper()
    elif operation == "reverse":
        result = text[::-1]
    else:
        result = len(text.split())

    return (
        jsonify(
            result=result,
            operation=operation,
            original_length=len(text),
        ),
        200,
    )


if __name__ == "__main__":
    app.run(debug=True, port=5000)
